import React, {
  PropsWithChildren,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

import {
  SegmentedSwitchThumb,
  SegmentedSwitchWrapper,
  StyledSwitchOption,
} from "./segmented-switch.style";

import { HtmlProps } from "../styles/theme";

export type SegmentedSwitchProps = {
  defaultValue?: number | null;
  clearable?: boolean;
  padding?: string;
  orientation?: "horizontal" | "vertical";

  onChange?: (value: number | null) => void;
};

const SegmentedSwitch: React.FC<
  PropsWithChildren<SegmentedSwitchProps & HtmlProps<HTMLDivElement>>
> = ({
  defaultValue = null,
  clearable = false,
  orientation = "horizontal",
  onChange,
  children,
  padding = "4px",
  htmlProps,
}) => {
  const [selected, setSelected] = useState<number | null>(defaultValue);

  const [animValue, setAnimValue] = useState(defaultValue ?? 0);

  const refPrevSelected = useRef<number | null>(null);

  const id = useId();

  const items = React.Children.toArray(children);

  useEffect(() => {
    if (refPrevSelected.current === null && selected === defaultValue) {
      return;
    }

    if (onChange && selected !== refPrevSelected.current) {
      refPrevSelected.current = selected;

      onChange(selected);
    }
  }, [selected, onChange, defaultValue]);

  const handleSelect = (index: number) => {
    setSelected((prev) => {
      if (clearable && prev === index) {
        return null;
      }

      setAnimValue(index);

      return index;
    });
  };

  const visible = selected !== null;

  const segmentSize = 100 / items.length;

  const horizontalWidth = `calc(${segmentSize}% - ${padding})`;

  const horizontalLeft =
    animValue === 0 ? `${padding}` : `calc(${segmentSize * animValue}%)`;

  const verticalHeight = `calc(${segmentSize}% - ${padding})`;

  const verticalTop =
    animValue === 0 ? `${padding}` : `calc(${segmentSize * animValue}%)`;

  return (
    <SegmentedSwitchWrapper
      {...htmlProps}
      $orientation={orientation}
      $padding={padding}
    >
      <SegmentedSwitchThumb
        $orientation={orientation}
        $visible={visible}
        $left={horizontalLeft}
        $width={horizontalWidth}
        $top={verticalTop}
        $height={verticalHeight}
      />

      {items.map((child, index) => {
        const active = index === selected;

        return (
          <StyledSwitchOption
            key={`${id}-${index}`}
            $active={active}
            $orientation={orientation}
            onClick={() => handleSelect(index)}
          >
            {child}
          </StyledSwitchOption>
        );
      })}
    </SegmentedSwitchWrapper>
  );
};

export default SegmentedSwitch;
