import { StyleBar, StyleContainer } from "./audioVisualizer.style";

export interface AudioVisualizerProps {
  count?: number;
  color?: string;
  speed?: number;
  width?: number;
  maxHeight?: number;
  borderRadius?: string;
  gap?: number;
}

const AudioVisualizer = ({
  count = 3,
  color = "#FD893A",
  speed = 1,
  width = 6,
  maxHeight = 32,
  borderRadius = "4px",
  gap = 4,
}: AudioVisualizerProps) => (
  <StyleContainer maxHeight={maxHeight} gap={gap}>
    {Array.from({ length: count }).map((_, i) => (
      <StyleBar
        key={i}
        $color={color}
        $width={width}
        $speed={speed}
        $borderRadius={borderRadius}
        $delay={i * (speed / count)}
      />
    ))}
  </StyleContainer>
);

AudioVisualizer.displayName = "AudioVisualizer";
export default AudioVisualizer;
